 void Start(){game=GetComponent<SurvivorGame>();platform=game.platform;font=Resources.Load<Font>("Fonts/Chinese");if(!font)font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");BuildHud();var go=new GameObject("Interaction Ray");rayLine=go.AddComponent<LineRenderer>();rayLine.sharedMaterial=new Material(Resources.Load<Shader>("Shaders/PointerOverlay"));rayLine.sortingOrder=100;rayLine.numCapVertices=4;rayLine.startWidth=.004f;rayLine.endWidth=.002f;rayLine.startColor=rayLine.endColor=new Color(.95f,.78f,.4f);rayLine.positionCount=2;var dot=GameObject.CreatePrimitive(PrimitiveType.Sphere);dot.name="UI Pointer Dot";Destroy(dot.GetComponent<Collider>());dot.GetComponent<Renderer>().sharedMaterial=rayLine.sharedMaterial;pointerDot=dot.transform;pointerDot.localScale=Vector3.one*.016f;dot.SetActive(false);}
