 static string EffectText(int i,int level){switch(i){case 0:return "生命 "+(100+10*level);case 1:return "伤害 "+(20+2*level);case 2:return (1-.05f*level).ToString("F2")+"秒";case 3:return (2+.1f*level).ToString("F1")+"米";case 4:return (.5f+.1f*level).ToString("F1")+"米";case 7:return "×"+(1+.15f*level).ToString("F2");default:return "×"+(1+.1f*level).ToString("F1");}}
 static string RarityName(Rarity rarity)=>new[]{"普通","稀有","史诗","传说"}[(int)rarity];
 static string TimeText(float time){int seconds=Mathf.Max(0,Mathf.FloorToInt(time));return (seconds/60).ToString("00")+":"+(seconds%60).ToString("00");}
 void Update(){if(!game||!platform.Head)return;if(previous!=game.screen||(game.screen==ScreenState.Progression&&previousMoney!=game.meta.crystals)||(game.screen==ScreenState.Upgrade&&previousOptions!=game.options.GetHashCode()))Build();if(game.screen==ScreenState.Menu&&statusText)statusText.text=platform.Status+(string.IsNullOrEmpty(game.notice)?"":"\n"+game.notice);
 if(game.screen==ScreenState.Menu&&menuStart)menuStart.interactable=game.Ready;
 if(game.screen==ScreenState.MR){if(mrText)mrText.text=platform.MR.Diagnostics;if(mrScan)mrScan.interactable=!platform.MR.State.Busy;if(mrRetry)mrRetry.interactable=!platform.MR.State.Busy&&!platform.Simulation;if(mrPreview)mrPreview.interactable=!platform.Simulation;if(mrPreview)mrPreview.GetComponentInChildren<Text>().text="空间网格预览："+(platform.MR.ShowMesh?"开":"关");}
 bool hudVisible=game.screen==ScreenState.Playing;if(hudVisible&&!hud.gameObject.activeSelf)placement.Reset();hud.gameObject.SetActive(hudVisible);hudGroup.alpha=hudVisible?1:0;hudPause.interactable=hudVisible;damageFlash.color=new Color(1,0,0,Mathf.Clamp01((game.DamageFlashUntil-Time.unscaledTime)/.3f)*.42f);
 var player=game.player;healthFill.rectTransform.localScale=new Vector3(Mathf.Clamp01(player.health/player.maxHealth),1,1);expFill.rectTransform.localScale=new Vector3(Mathf.Clamp01((float)player.experience/player.required),1,1);bossFill.transform.parent.gameObject.SetActive(game.Boss.active);bossText.gameObject.SetActive(game.Boss.active);if(game.Boss.active){bossText.text="古树守望者  "+game.Boss.hp+" / "+game.Boss.maxHp;bossFill.rectTransform.localScale=new Vector3(Mathf.Clamp01((float)game.Boss.hp/game.Boss.maxHp),1,1);}
 if(Time.unscaledTime>nextHud){nextHud=Time.unscaledTime+.1f;healthText.text="生命 "+Mathf.CeilToInt(player.health)+" / "+player.maxHealth+"    护盾 "+Mathf.CeilToInt(player.shield);healthText.color=player.health<=player.maxHealth*.25f?new Color(1,.3f,.25f):Color.white;expText.text="Lv."+player.level+"   经验 "+player.experience+" / "+player.required+"   波次 "+SurvivorRules.Wave(player.elapsed)+"   Boss "+TimeText(600-player.elapsed);for(int i=0;i<9;i++){var id=SurvivorRules.Weapons[i];skillTiles[i].SetActive(player.Owns(id));skillLevels[i].text=ShortSkillName(i)+" "+player.Stack(id);}statsText.text="伤害 "+player.damage+"  间隔 "+player.interval.ToString("F2")+"秒  范围 "+player.range.ToString("F1")+"米  弹数 "+player.projectiles+"\n恢复 "+player.regeneration.ToString("F1")+"/秒  拾取 "+player.pickup.ToString("F1")+"米  经验 ×"+player.experienceMultiplier.ToString("F2");noticeText.text=(game.Ready?game.notice:platform.Status);if(game.screen==ScreenState.Progression)noticeText.text=game.notice;}
 }
 void LateUpdate(){TickPreview();if(!game||!platform||!platform.Head||!hud)return;if(hud.gameObject.activeSelf){placement.Tick(platform.Head.transform,Time.unscaledDeltaTime);hud.transform.SetPositionAndRotation(placement.Position,placement.Rotation);}UpdatePointer();}
 static string ShortSkillName(int i)=>new[]{"飞剑","能量弹","毒雾","闪电","冰锥","熔岩","黑洞","剑雨","雷域"}[i];
 Button Hit(Canvas canvas,List<Button> candidates,Ray ray,ref float distance){if(!canvas||!canvas.gameObject.activeInHierarchy)return null;var plane=new Plane(canvas.transform.forward,canvas.transform.position);if(!plane.Raycast(ray,out var enter)||enter<0||enter>=distance)return null;var point=ray.GetPoint(enter);foreach(var button in candidates)if(button&&button.interactable&&button.gameObject.activeInHierarchy){var rect=button.GetComponent<RectTransform>();var local=rect.InverseTransformPoint(point);if(rect.rect.Contains(new Vector2(local.x,local.y))){distance=enter;return button;}}return null;}
 // Clip the visual beam at every menu surface, including non-button artwork.
 // Hit testing keeps its own distance so empty menu space cannot accept clicks.
 static float PointerSurfaceDistance(Canvas canvas,Ray ray,float distance){if(!canvas||!canvas.gameObject.activeInHierarchy)return distance;var plane=new Plane(canvas.transform.forward,canvas.transform.position);if(!plane.Raycast(ray,out var enter)||enter<=0||enter>=distance)return distance;var rect=(RectTransform)canvas.transform;var local=rect.InverseTransformPoint(ray.GetPoint(enter));return rect.rect.Contains(new Vector2(local.x,local.y))?enter:distance;}
 void UpdatePointer(){bool valid=platform.Pointer(out var ray,out var pressed);if(valid&&platform.PointerSource!=SurvivorPointerSource.Mouse)ray=pointerRayFilter.Step(ray,platform.PointerSource,Time.unscaledDeltaTime);else pointerRayFilter.Reset();ApplyPointer(valid,platform.PointerSource,ray,pressed);}
 void ApplyPointer(bool valid,SurvivorPointerSource source,Ray ray,bool pressed){
  float distance=6;Button next=null;
  // Floating controls stay usable even when a partial scan places a noisy
  // room triangle between the hand and a visible menu.
  if(valid){next=Hit(panel,buttons,ray,ref distance);var onHud=Hit(hud,hudButtons,ray,ref distance);if(onHud)next=onHud;}
  // Retain only a currently visible, previously hovered control, and only
  // within 12 canvas units (~12 mm). A different exact hit takes priority.
  if(valid&&!next&&source!=SurvivorPointerSource.Mouse&&source==lastPointerSource&&hovered&&hovered.interactable&&hovered.gameObject.activeInHierarchy){var canvas=hovered.GetComponentInParent<Canvas>();var plane=new Plane(canvas.transform.forward,canvas.transform.position);if(plane.Raycast(ray,out var enter)&&enter>0&&enter<distance){var rect=hovered.GetComponent<RectTransform>();var local=rect.InverseTransformPoint(ray.GetPoint(enter));var bounds=rect.rect;bounds.xMin-=12;bounds.xMax+=12;bounds.yMin-=12;bounds.yMax+=12;if(bounds.Contains(new Vector2(local.x,local.y))){next=hovered;distance=enter;}}}
  if(lastPointerValid&&!valid)trackingLosses++;if(valid&&lastPointerValid&&source!=lastPointerSource)sourceSwitches++;lastPointerValid=valid;lastPointerSource=source;
  if(hovered!=next){if(hovered)hovered.transform.localScale=Vector3.one;hovered=next;if(hovered)hovered.transform.localScale=Vector3.one*1.035f;}
  bool show=valid&&!platform.Simulation&&(panel||hud.gameObject.activeSelf);
  float visibleDistance=PointerSurfaceDistance(panel,ray,distance);visibleDistance=PointerSurfaceDistance(hud,ray,visibleDistance);
  rayLine.enabled=show;rayLine.SetPosition(0,ray.origin);rayLine.SetPosition(1,ray.GetPoint(Mathf.Max(0,visibleDistance-.004f)));
  var color=next?(pressed?Color.green:Color.cyan):new Color(.4f,.6f,.8f);rayLine.startColor=rayLine.endColor=color;
  if(pointerDot){pointerDot.gameObject.SetActive(show&&next);pointerDot.position=ray.GetPoint(Mathf.Max(0,distance-.012f));pointerDot.localScale=Vector3.one*(pressed?.022f:.016f);}
  if(inputText)inputText.text=platform.PointerStatus+(pressed?" · 扳机 / 捏合按下":" · 松开扳机后瞄准并按下")+(next?" · "+next.name:"");
  bool click=pointerClick.Step(valid,source,pressed);
  if(click&&!next){missedPresses++;Debug.Log("[SurvivorUI] Miss "+source+" (no button at press) "+platform.TriggerStatus);}
  if(click&&next){lastClick=next.name;clickCount++;Debug.Log("[SurvivorUI] Click "+source+" -> "+lastClick);next.onClick.Invoke();}
  if(Debug.isDebugBuild&&(click||Time.unscaledTime>=nextInputReport)){nextInputReport=Time.unscaledTime+2;try{System.IO.File.WriteAllText(System.IO.Path.Combine(Application.persistentDataPath,"ui-input.txt"),"screen="+game.screen+"\nsource="+source+"\nvalid="+valid+"\npressed="+pressed+"\nhover="+(next?next.name:"")+"\nclicks="+clickCount+"\nlastClick="+lastClick+"\nmissedPresses="+missedPresses+"\nsourceSwitches="+sourceSwitches+"\ntrackingLosses="+trackingLosses+"\ntrigger="+platform.TriggerStatus);}catch(System.IO.IOException){}}
 }
